// End-to-end test against REAL containers: deploy a stack generated by the engine, wire it with the
// connectors, wire it again to prove it is idempotent, then remove everything it created.
//   npm run build && node scripts/e2e.mjs
// Uses its own project name and ports, so it never touches another stack. Needs Docker, no VPN.
import { execFileSync, spawnSync } from "node:child_process";
import { randomBytes } from "node:crypto";
import { mkdtempSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { fileURLToPath } from "node:url";
import { syncProfiles } from "../packages/connectors/dist/index.js";
import { loadCatalog } from "../packages/core/dist/index.js";
import {
  checkDocker,
  composeDown,
  composePull,
  composeToYaml,
  composeUp,
  generateCompose,
  checkStorage,
  keyVar,
  networkName,
  prepareStorage,
  readQbitFirstRunPassword,
  runRecyclarr,
  writeProject,
} from "../packages/engine/dist/index.js";
import { SELECTED, addressing, makeContext, makePlan } from "./e2e-common.mjs";

const repo = fileURLToPath(new URL("..", import.meta.url));
const project = process.env.E2E_PROJECT ?? "homeport-e2e";
const hostPorts = {
  prowlarr: { web: 39696 },
  sonarr: { web: 38989 },
  radarr: { web: 37878 },
  qbittorrent: { web: 38080 },
  jellyfin: { web: 38096 },
  seerr: { web: 35055 },
};
const say = (m) => console.log(`[e2e] ${m}`);
const hex = () => randomBytes(16).toString("hex");

const problem = await checkDocker();
if (problem) {
  console.error(problem);
  process.exit(1);
}

const catalog = loadCatalog();
const plan = makePlan(project, hostPorts);
const dir = mkdtempSync(join(tmpdir(), "homeport-e2e-"));
const proj = { dir, project };
const secrets = { QBIT_PASS: hex(), JELLYFIN_PASS: hex() };
for (const id of ["prowlarr", "sonarr", "radarr"]) secrets[keyVar(catalog.apps.get(id))] = hex();

let failed = false;
const check = (name, ok, detail = "") => {
  if (!ok) failed = true;
  say(`${ok ? "PASS" : "FAIL"}  ${name}${detail ? `  (${detail})` : ""}`);
};

try {
  const dotEnv = Object.entries(secrets).map(([k, v]) => `${k}=${v}`).join("\n");
  await writeProject(proj, composeToYaml(generateCompose(catalog, plan)), `${dotEnv}\n`);
  say(`project ${project} written to ${dir}`);

  say("pulling images (first run downloads several GB)...");
  await composePull(proj);
  await composeUp(proj);
  const location = { mode: "volume", project };
  const owner = { puid: plan.puid, pgid: plan.pgid };
  await prepareStorage(location, owner);
  const storage = await checkStorage(location, owner);
  check("storage check finds no failures", storage.results.every((r) => r.status !== "fail"), storage.tier);
  check("storage links files instead of copying", !storage.copyMode, `${storage.measured.fsType}, ${Math.round(storage.measured.writeMBps ?? 0)} MB/s`);
  const first = await readQbitFirstRunPassword(project);
  check("qBittorrent printed its one-time password", Boolean(first));

  // The wiring runs inside the stack's network, the same place Homeport itself will live.
  const helper = (phase) => {
    const env = { ...process.env, ...secrets, E2E_ADDR: JSON.stringify(addressing(plan)), QBIT_FIRST_RUN: first ?? "" };
    const names = [...Object.keys(secrets), "E2E_ADDR", "QBIT_FIRST_RUN"].flatMap((k) => ["-e", k]);
    const r = spawnSync(
      "docker",
      ["run", "--rm", "--network", networkName(project), "-v", `${repo}:/work:ro`, "-w", "/work", ...names,
        "node:22-alpine", "node", "scripts/e2e-phase.mjs", phase],
      { env, encoding: "utf8" },
    );
    if (r.status !== 0) throw new Error(`phase ${phase} failed:\n${r.stdout}\n${r.stderr}`.slice(-1500));
    return r.stdout.split("\n").filter((l) => l.startsWith("LOG ")).map((l) => l.slice(4));
  };
  const profiles = async () => {
    const logs = [];
    const ctx = makeContext(plan, { ...secrets, QBIT_FIRST_RUN: first ?? "" }, (m) => logs.push(m));
    await syncProfiles(ctx, SELECTED, { runRecyclarr: (cfg) => runRecyclarr(project, cfg) });
    return logs;
  };
  const wire = async () => [...helper("apps"), ...(await profiles()), ...helper("requests")];

  say("wiring (first run)...");
  const run1 = await wire();
  run1.forEach((l) => say(`  ${l}`));
  const has = (logs, re) => logs.some((l) => re.test(l));
  check("qBittorrent configured", has(run1, /qBittorrent: password set/));
  check("Sonarr and Radarr got a download client", has(run1, /Sonarr: added qBittorrent/) && has(run1, /Radarr: added qBittorrent/));
  check("Prowlarr linked to both", has(run1, /Prowlarr: linked Sonarr/) && has(run1, /Prowlarr: linked Radarr/));
  check("Jellyfin set up with both libraries", has(run1, /Jellyfin: finished first-run/) && has(run1, /library Movies/) && has(run1, /library TV Shows/));
  check("Recyclarr created the TRaSH profiles", has(run1, /Recyclarr/));
  check("Seerr connected and linked both managers", has(run1, /Seerr: linked Radarr/) && has(run1, /Seerr: linked Sonarr/) && has(run1, /setup marked complete/));

  say("wiring again (must change nothing)...");
  const run2 = await wire();
  const changes = run2.filter((l) => /added|linked|finished|enabled|connected|marked|now reached/i.test(l));
  check("second run is idempotent", changes.length === 0, changes.join("; "));
} catch (e) {
  failed = true;
  console.error(`[e2e] ERROR ${e instanceof Error ? e.message : e}${e?.detail ? `
${e.detail}` : ""}`);
} finally {
  say("tearing down the test stack...");
  await composeDown(proj, { volumes: true }).catch((e) => console.error(`[e2e] teardown: ${e.detail ?? e.message}`));
  execFileSync("docker", ["volume", "rm", "-f", `${project}_recyclarr-run`], { stdio: "ignore" });
}
say(failed ? "FAILED" : "ALL PASSED");
process.exit(failed ? 1 : 0);
